        make_gmem_ptr(input),
        make_shape(N, 3, H, W),
        make_stride(3 * H * W, H * W, W, 1));
    auto g_weight = make_tensor(
        make_gmem_ptr(weight),
        make_shape(32, 3, 3, 3),
        make_stride(27, 9, 3, 1));
    auto g_output = make_tensor(
        make_gmem_ptr(output),
        make_shape(N, 32, Ho, Wo),
        make_stride(32 * Ho * Wo, Ho * Wo, Wo, 1));
    auto s_input = make_tensor(
        make_smem_ptr(smem_input),
        make_shape(Int<3>{}, Int<IN_TILE_H>{}, Int<IN_TILE_W>{}));
    auto s_weight = make_tensor(
        make_smem_ptr(smem_weight),
        make_shape(Int<TILE_C>{}, Int<3>{}, Int<3>{}, Int<3>{}));
    for (int linear = tid; linear < 3 * IN_TILE_H * IN_TILE_W; linear += THREADS) {
        const int c = linear / (IN_TILE_H * IN_TILE_W);
        const int rem = linear % (IN_TILE_H * IN_TILE_W);
        const int iy = rem / IN_TILE_W;
        const int ix = rem % IN_TILE_W;
        const int gy = tile_y + iy;
        const int gx = tile_x + ix;
        if (gy < H && gx < W) {
            s_input(c, iy, ix) = g_input(batch, c, gy, gx);
        } else {
            s_input(c, iy, ix) = __float2bfloat16(0.0f);
        }
    }
    for (int linear = tid; linear < TILE_C * 3 * 3 * 3; linear += THREADS) {
        const int local_oc = linear / 27;
        const int rem0 = linear % 27;
        const int ic = rem0 / 9;
        const int rem1 = rem0 % 9;
        const int ky = rem1 / 3;
        const int kx = rem1 % 3;
        const int oc = channel_base + local_oc;
        if (oc < 32) {
            s_weight(local_oc, ic, ky, kx) = g_weight(oc, ic, ky, kx);
        } else {
            s_weight(local_oc, ic, ky, kx) = __float2bfloat16(0.0f);
        }
    }
    __syncthreads();
    const int pair = tid & 63;
    const int first_pixel = pair * 2;
    const int local_y = first_pixel / TILE_W;
    const int local_x0 = first_pixel % TILE_W;
    const int local_x1 = local_x0 + 1;
    const int local_channel = tid / 64;
    const int oy = tile_y + local_y;
    const int ox0 = tile_x + local_x0;
    const int ox1 = tile_x + local_x1;
    float acc00 = 0.0f;
    float acc01 = 0.0f;
    float acc10 = 0.0f;
    float acc11 = 0.0f;
    if (oy < Ho) {
        for (int ic = 0; ic < 3; ++ic) {
            for (int ky = 0; ky < 3; ++ky) {
                for (int kx = 0; kx < 3; ++kx) {
                    const float x0 = __bfloat162float(
                        s_input(ic, local_y + ky, local_x0 + kx));
                    const float x1 = __bfloat162float(
                        s_input(ic, local_y + ky, local_x1 + kx));
                    const float w0 = __bfloat162float(
                        s_weight(local_channel, ic, ky, kx));
                    const float w1 = __bfloat162float(
                        s_weight(local_channel + 4, ic, ky, kx));
                    if (ox0 < Wo) {
                        acc00 += x0 * w0;
                        acc01 += x0 * w1;
                    }
                    if (ox1 < Wo) {
                        acc10 += x1 * w0;
                        acc11 += x1 * w1;
                    }
                }
            }
        }
        const int oc0 = channel_base + local_channel;
        const int oc1 = oc0 + 4;
        if (ox0 < Wo) {
            if (oc0 < 32) {
                g_output(batch, oc0, oy, ox0) = __float2bfloat16(acc00);
            }
            if (oc1 < 32) {
                g_output(batch, oc1, oy, ox0) = __float2bfloat16(acc01);
            }
        }
        if (ox1 < Wo) {
            if (oc0 < 32) {
                g_output(batch, oc0, oy, ox1) = __float2bfloat16(acc10);
            }
            if (oc1 < 32) {
                g_output(batch, oc1, oy, ox1) = __float2bfloat16(acc11);
            }
        }
    }
}


